  Lemma pm_nt_find : forall (w : pmw MI ST) A M model c (fx : FPState) R (tid : Z) K,
    PMX w A M model c -> getr R 10%bv = Z_to_bv 64 (w_p w) -> getr R 8%bv = Z_to_bv 64 (PrsNeeds.sx32 tid) -> 0 <= tid < 2 ^ 32 ->
